import { mountShell } from '../components/layout.js';import { repositories } from '../repositories/resourceRepository.js';import { resourceCard } from '../components/resourceCard.js';
mountShell('التأسيس',`<div class="toolbar"><input id="search" type="search" placeholder="ابحث في التأسيس..."><select id="level"><option value="">كل المستويات</option><option value="beginner">مبتدئ</option><option value="intermediate">متوسط</option><option value="advanced">متقدم</option></select></div><div id="list" class="grid"></div><button id="more" class="button" hidden>تحميل المزيد</button>`);const list=document.getElementById('list');let cursor=null,busy=false;async function load(reset=false){if(busy)return;busy=true;if(reset){cursor=null;list.innerHTML=''}try{const r=await repositories.foundations.page({title:document.getElementById('search').value.trim(),level:document.getElementById('level').value},24,cursor);if(r.rows.length)list.insertAdjacentHTML('beforeend',r.rows.map(x=>resourceCard({...x,icon:'🧠'})).join(''));cursor=r.nextCursor;document.getElementById('more').hidden=!r.hasMore;if(!r.rows.length&&!list.children.length)list.innerHTML='<div class="empty">لا يوجد تأسيس مطابق.</div>'}catch(e){console.error(e);list.innerHTML='<div class="error-box">تعذر تحميل التأسيس.</div>'}finally{busy=false}}document.getElementById('search').addEventListener('input',()=>load(true));document.getElementById('level').addEventListener('change',()=>load(true));document.getElementById('more').addEventListener('click',()=>load());load(true);